166: static inline int
167: queue_peek(struct libevdev *dev, size_t idx, struct input_event *ev)
168: {
169: 	if (dev->queue_next == 0 || idx > dev->queue_next)
170: 		return 1;
171: 	*ev = dev->queue[idx];
172: 	return 0;
173: }
